# /// script
# requires-python = ">=3.12"
# dependencies = ["playwright>=1.51", "websockets>=14"]
# ///
"""Browser calibration regression with a local fake controller; never opens hardware."""
import argparse
import json
from pathlib import Path
import threading
import time
from urllib.parse import urlencode

from playwright.sync_api import expect, sync_playwright
from websockets.exceptions import ConnectionClosed
from websockets.sync.server import serve

OUTPUT = Path(__file__).resolve().parents[2] / 'runs' / 'calibration-check'
# The status Wearable Lab really publishes, generated by wearable_test/test_console.py.
FIXTURE = Path(__file__).resolve().parents[1] / 'src' / 'telemetry' / 'fixtures' / 'calibration_full.json'
LAB_SECTIONS = ('physical', 'response', 'arm_settings', 'directions', 'coins', 'wearable', 'geometry')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--url', default='http://127.0.0.1:5173')
    args = parser.parse_args()
    OUTPUT.mkdir(parents=True, exist_ok=True)
    state = dict(session='browser-test', revision=0, phase='needs_pose_a', capture_pose=None,
                 remaining_s=0, input_fresh=True, sensors=[True]*3, can_recenter=False,
                 detail='Start with pose A.', request=None, range_capture=True,pan_capture=True,motion_ranges={},
                 saved_config=dict(path='wearable_test/calibration.local.json',state='none',detail='Calibration saves automatically.'),
                 tuning=dict(values=dict(speed_deg_s=240,claw_speed_per_s=2,max_load=650,gripper_max_load=350,
                                         load_stops_enabled=False,gripper_contact_load=180,gripper_hold_load=120),revision=0,applied_revision=0,
                             connected=True,fresh=True,enabled=False,request=None,can_reconnect=False,detail='',reconnect_request=None,
                             grasp=dict(holding=False,load=0,detail='Contact detection ready.')),
                 slider=dict(referenced=False,enabled=False,pos=None,target=None,detail='Reference slider.',request=None),
                 replay=dict(phase='empty',revision=0,duration_s=0,elapsed_s=0,samples=0,includes_slider=False,
                             detail='Double-click to record.',request=None))
    lab = json.loads(FIXTURE.read_text(encoding='utf-8'))
    state.update({key: lab[key] for key in LAB_SECTIONS}, control_request=None)
    state['physical'].update(can_enable_arm=False, can_enable_claw=False, mode='off', message='COM6: connected, read only.')
    for section in ('arm_settings', 'directions', 'coins'): state[section]['request'] = None
    state['response'].update(pending=None, pending_profile=None, profile=4)
    lock = threading.Lock()
    options = dict(publish=True, acknowledge=True, reject=False, old=False)
    commands = []

    def change(**values):
        with lock: state.update(values)

    def handle(ws):
        try:
            while True:
                try: frame = ws.recv(timeout=.05)
                except TimeoutError: frame = None
                with lock:
                    if frame:
                        command = json.loads(frame.split(' ', 1)[1])
                        if command.get('type') == 'replay_robot':
                            commands.append(command)
                            assert command['revision'] == state['revision']
                            replay = state['replay']
                            assert command['replay_revision'] == replay['revision']
                            if options['acknowledge']:
                                if not options['reject']:
                                    replay['revision'] += 1
                                    if command['action']=='record':
                                        recording = replay['phase']!='recording'
                                        replay.update(phase='recording' if recording else 'ready',
                                            duration_s=0 if recording else 2,samples=1 if recording else 101,
                                            detail='Recording motion.' if recording else 'Recording ready.')
                                    elif command['action']=='play': replay.update(phase='returning',elapsed_s=0,detail='Returning to the first pose.')
                                    else: replay.update(phase='ready',detail='Replay stopped.')
                                replay['request'] = dict(id=command['request_id'],ok=not options['reject'],applied=not options['reject'],
                                    detail='Replay refused.' if options['reject'] else replay['detail'])
                        if command.get('type') == 'reconnect_robot':
                            commands.append(command)
                            assert command['revision'] == state['revision']
                            state['revision'] += 1
                            state['tuning'].update(connected=True,fresh=True,can_reconnect=False,
                                reconnect_request=dict(id=command['request_id'],ok=True,detail='Reconnecting, read only.'))
                        if command.get('type') == 'tune_robot':
                            commands.append(command)
                            assert command['revision'] == state['tuning']['revision']
                            if options['acknowledge']:
                                tuning = state['tuning']
                                if not options['reject']:
                                    response = state['response']
                                    if 'changes' in command:
                                        changes = dict(command['changes'])
                                        leads = changes.pop('joint_lead_deg', {})
                                        tuning['values'].update({k: v for k, v in changes.items() if k in tuning['values']})
                                        response['values'].update({k: v for k, v in changes.items() if k in response['values']})
                                        response['values']['joint_lead_deg'].update(leads)
                                        if leads or set(changes) & {'response_ms', 'control_hz'}: response['profile'] = None
                                    elif 'profile' in command: response['profile'] = command['profile']
                                    else: response['profile'] = 4
                                    tuning['revision'] += 1
                                    tuning['applied_revision'] = tuning['revision']
                                tuning['request'] = dict(id=command['request_id'],ok=not options['reject'],applied=not options['reject'],
                                    revision=tuning['revision'],detail='Settings refused.' if options['reject'] else 'Settings applied.')
                        if command.get('type') == 'control_slider':
                            commands.append(command)
                            assert command['revision'] == state['revision']
                            state['revision'] += 1
                            slider = state['slider']
                            action = command['action']
                            slider['request'] = dict(id=command['request_id'],ok=True,detail='Requested.')
                            if action in ('zero','hundred'):
                                slider.update(referenced=True,enabled=False,pos=0 if action=='zero' else 100,target=None,detail='Slider referenced.')
                            elif action=='enable': slider.update(enabled=True,detail='Joystick X controls slider speed; center holds.')
                            else: slider.update(enabled=False,referenced=False,pos=None,target=None,detail='Slider released.')
                        if command.get('type') == 'control_robot':
                            commands.append(command)
                            physical = state['physical']
                            if command['action'] == 'stop':
                                physical.update(mode='paused', claw_enabled=False, message='PAUSED: operator Stop / Esc. Manual enable required.')
                                state['revision'] += 1
                                state['control_request'] = dict(id=command['request_id'], ok=True, applied=True, detail='Stopped.')
                            else:
                                assert command['session'] == state['session'] and command['revision'] == state['revision']
                                if command['action'] == 'enable_arm':
                                    physical.update(mode='aligning', can_enable_arm=False, message='ALIGNING to captured URDF pose (90 deg/s).')
                                else: physical.update(claw_enabled=True, message='Claw enabled.')
                                state['control_request'] = dict(id=command['request_id'], ok=True, applied=True, detail=physical['message'])
                        if command.get('type') == 'configure_arm':
                            commands.append(command)
                            assert command['revision'] == state['revision']
                            state['arm_settings']['values'] = command['settings']
                            state['arm_settings']['request'] = dict(id=command['request_id'], ok=True, detail='Settings saved. Capture pose A to start calibration.')
                            state['revision'] += 1
                        if command.get('type') == 'set_joint_direction':
                            commands.append(command)
                            assert command['revision'] == state['revision']
                            state['directions']['reverse'][command['joint']] = command['reverse']
                            state['directions']['request'] = dict(id=command['request_id'], ok=True, detail='Direction changed.')
                            state['revision'] += 1
                        if command.get('type') == 'test_haptic_motor':
                            commands.append(command)
                            coin = state['coins']['motors'][command['motor']]
                            if command['action'] in ('test', 'run'):
                                coin.update(output=command['percent'], running_s=1 if command['action'] == 'test' else 10, acks=coin['acks'] + 1)
                            elif command['action'] == 'stop': coin.update(output=0, running_s=0)
                            coin['percent'] = command['percent']
                            state['coins']['request'] = dict(id=command['request_id'], ok=True, detail='Coin command applied.')
                        if command.get('type') == 'calibrate_arm':
                            commands.append(command)
                            assert command['session'] == state['session']
                            if options['acknowledge']:
                                state['request'] = dict(id=command['request_id'], ok=not options['reject'],
                                                        detail='Controller refused capture.' if options['reject'] else 'Capture started.')
                                if not options['reject']:
                                    state['revision'] += 1
                                    if command['action'] == 'cancel':
                                        state.update(phase='needs_pose_a', capture_pose=None, remaining_s=0, detail='Capture cancelled; arm held.')
                                    else:
                                        state.update(phase='preparing', capture_pose={'capture_a':'A', 'capture_b':'B', 'capture_elbow':'C', 'capture_shoulder':'D', 'capture_pan_left':'E','capture_pan_right':'F','recenter':'R'}[command['action']],
                                                     remaining_s=3, detail='Get into position.')
                    if options['publish']:
                        ws.send('calibration ' + json.dumps(dict(state, t=time.time() - (10 if options['old'] else 0))))
        except ConnectionClosed:
            pass

    with serve(handle, '127.0.0.1', 0) as server:
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        port = server.socket.getsockname()[1]
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch(channel='chrome', headless=True)
            page = browser.new_page(viewport={'width':1440, 'height':1050})
            errors = []
            page.on('pageerror', lambda error: errors.append(str(error)))
            query = urlencode(dict(source='live', wsUrl=f'ws://127.0.0.1:{port}', cameraUrl=''))
            page.goto(args.url.rstrip('/') + '/?' + query, wait_until='domcontentloaded')
            panel = page.get_by_role('region', name='Arm-to-robot calibration')
            tuning = page.get_by_role('region', name='Robot speed & load')
            stops = tuning.get_by_role('checkbox', name='Software load stops')
            apply = tuning.get_by_role('button', name='Apply settings', exact=True)
            expect(stops).not_to_be_checked()
            expect(tuning.get_by_label('Arm speed', exact=True)).to_have_value('240')
            expect(apply).to_be_disabled()
            control = page.get_by_role('region', name='Robot control')
            with lock:
                state['tuning'].update(connected=False,fresh=False,can_reconnect=True,detail='COM6: motors did not reply.')
            reconnect_robot = control.get_by_role('button',name='Reconnect robot',exact=True)
            expect(reconnect_robot).to_be_enabled()
            expect(control.get_by_text('COM6: motors did not reply.',exact=True)).to_be_visible()
            expect(tuning.get_by_label('Arm speed',exact=True)).to_be_disabled()
            reconnect_robot.click()
            expect(reconnect_robot).to_have_count(0)
            expect(tuning.get_by_label('Arm speed',exact=True)).to_be_enabled()
            with lock: assert state['tuning']['enabled'] is False
            tuning.get_by_label('Arm load cutoff', exact=True).fill('750')
            tuning.get_by_label('Gripper load cutoff', exact=True).fill('450')
            stops.check()
            apply.click()
            expect(tuning.get_by_text('Applied: 750 raw counts')).to_be_visible()
            expect(tuning.get_by_text('Settings applied.', exact=True)).to_be_visible()
            expect(tuning.get_by_label('Arm speed', exact=True)).to_have_value('240')
            tuning.get_by_label('Arm speed', exact=True).fill('361')
            expect(apply).to_be_disabled()
            tuning.get_by_role('button', name='Discard edits').click()
            tuning.get_by_label('Claw speed', exact=True).fill('1.5')
            with lock: options['reject'] = True
            apply.click()
            expect(tuning.get_by_role('alert')).to_have_text('Settings refused.')
            with lock: options['reject'] = False
            tuning.get_by_role('button', name='Discard edits').click()
            stops.uncheck()
            apply.click()
            expect(tuning.get_by_text('Settings applied.', exact=True)).to_be_visible()
            expect(stops).not_to_be_checked()
            expect(tuning.get_by_label('Grip contact load',exact=True)).to_have_value('180')
            expect(tuning.get_by_label('Grip holding load',exact=True)).to_have_value('120')
            tuning.get_by_label('Grip holding load',exact=True).fill('200')
            expect(apply).to_be_disabled()
            tuning.get_by_label('Grip contact load',exact=True).fill('220')
            apply.click()
            expect(tuning.get_by_text('Applied: 200 raw counts')).to_be_visible()
            with lock: state['tuning']['grasp'].update(holding=True,load=200,detail='Holding object from sustained closing contact.')
            expect(tuning.get_by_text('Holding object',exact=True)).to_be_visible()
            tuning.screenshot(path=str(OUTPUT / 'grasp-desktop.png'))
            with lock: state['tuning']['grasp'].update(holding=False,load=0,detail='Contact detection ready.')
            tuning.screenshot(path=str(OUTPUT / 'tuning-desktop.png'))
            a = panel.get_by_role('button', name='Capture pose A', exact=True)
            b = panel.get_by_role('button', name='Capture pose B', exact=True)
            recenter = panel.get_by_role('button', name='Recenter arm', exact=True)
            expect(a).to_be_enabled()
            expect(b).to_be_disabled()
            expect(recenter).to_be_disabled()
            elbow = panel.get_by_role('button', name='Learn elbow bend', exact=True)
            shoulder = panel.get_by_role('button', name='Learn shoulder reach', exact=True)
            expect(elbow).to_be_disabled()
            expect(shoulder).to_be_disabled()
            a.click()
            expect(panel.get_by_text('Get ready · Pose A · 3s')).to_be_visible()
            expect(a).to_be_disabled()
            change(phase='sampling', remaining_s=1)
            expect(panel.get_by_text('Hold still · Pose A · 1s')).to_be_visible()
            change(phase='needs_pose_b', capture_pose=None, remaining_s=0, detail='Pose A saved. Lower your arm for B.')
            expect(b).to_be_enabled()
            b.click()
            expect(panel.get_by_text('Get ready · Pose B · 3s')).to_be_visible()
            change(phase='ready', capture_pose=None, remaining_s=0, can_recenter=True, detail='Calibrated. Mounting saved.')
            expect(panel.get_by_text('Calibrated', exact=True)).to_be_visible()
            expect(recenter).to_be_enabled()
            expect(panel.get_by_text('Calibration ready.', exact=False)).to_be_visible()
            elbow.click()
            expect(panel.get_by_text('Get ready · Bent elbow · 3s')).to_be_visible()
            change(phase='ready', capture_pose=None, remaining_s=0, motion_ranges={'elbow_max_deg':125}, detail='Elbow range saved.')
            expect(panel.get_by_text('Saved: straight to 125° bend')).to_be_visible()
            shoulder.click()
            expect(panel.get_by_text('Get ready · Arm raised · 3s')).to_be_visible()
            change(phase='ready', capture_pose=None, remaining_s=0, motion_ranges={'elbow_max_deg':125,'shoulder_min_deg':-90,'shoulder_max_deg':80}, detail='Shoulder range saved.')
            expect(panel.get_by_text('Saved: -90° to +80° elevation')).to_be_visible()
            pan_left = panel.get_by_role('button',name='Learn pan left',exact=True)
            pan_right = panel.get_by_role('button',name='Learn pan right',exact=True)
            pan_left.click()
            expect(panel.get_by_text('Get ready · Pan left · 3s')).to_be_visible()
            expect(pan_right).to_be_disabled()
            change(phase='ready',capture_pose=None,remaining_s=0,
                   motion_ranges={'elbow_max_deg':125,'shoulder_min_deg':-90,'shoulder_max_deg':80,'pan_left_deg':40})
            expect(panel.get_by_text('Left saved: 40°')).to_be_visible()
            pan_right.click()
            expect(panel.get_by_text('Get ready · Pan right · 3s')).to_be_visible()
            change(phase='ready',capture_pose=None,remaining_s=0,
                   motion_ranges={'elbow_max_deg':125,'shoulder_min_deg':-90,'shoulder_max_deg':80,'pan_left_deg':40,'pan_right_deg':30},
                   saved_config=dict(path='wearable_test/calibration.local.json',state='saved',detail='Mounting and ranges saved. Recenter after restarting.'))
            expect(panel.get_by_text('Right saved: 30°')).to_be_visible()
            expect(panel.get_by_text('Configuration saved automatically',exact=True)).to_be_visible()
            panel.screenshot(path=str(OUTPUT / 'pan-desktop.png'))
            # Run the robot from the console: enable needs the controller's go-ahead; Esc stops even while typing.
            align = control.get_by_role('button', name='Align & follow', exact=True)
            expect(align).to_be_disabled()
            with lock: state['physical'].update(can_enable_arm=True, can_enable_claw=True)
            expect(align).to_be_enabled()
            align.click()
            expect(control.get_by_text('Aligning', exact=True)).to_be_visible()
            expect(align).to_be_disabled()
            with lock: assert [c['action'] for c in commands if c['type'] == 'control_robot'] == ['enable_arm']
            control.get_by_text('Joint table').click()
            expect(control.get_by_role('rowheader', name='Elbow')).to_be_visible()
            control.screenshot(path=str(OUTPUT / 'robot-control-desktop.png'))
            tuning.get_by_label('Arm speed', exact=True).focus()
            page.keyboard.press('Escape')
            expect(control.get_by_text('Paused', exact=True)).to_be_visible()
            with lock: assert commands[-1]['type'] == 'control_robot' and commands[-1]['action'] == 'stop'
            page.get_by_role('banner').get_by_role('button', name='STOP / hold').click()
            page.wait_for_timeout(200)
            with lock: assert [c['action'] for c in commands if c['type'] == 'control_robot'] == ['enable_arm', 'stop', 'stop']
            with lock: state['physical'].update(mode='off', can_enable_arm=True)
            # The Setup page: every desktop dev window's controls, in calibration order.
            page.get_by_role('link', name='Setup', exact=True).click()
            expect(page.get_by_role('heading', name='Setup', level=1)).to_be_visible()
            feel = page.get_by_role('region', name='How the arm feels')
            feel.get_by_role('radio', name='Balanced').click()
            expect(feel.get_by_text('Applied: Balanced')).to_be_visible()
            with lock: assert commands[-1]['type'] == 'tune_robot' and commands[-1]['profile'] == 2 and 'changes' not in commands[-1]
            feel.get_by_text('Advanced', exact=True).click()
            feel.get_by_role('slider', name='Smoothing').fill('40')
            expect(feel.get_by_text('Applied: Custom (advanced)')).to_be_visible()
            with lock: assert commands[-1]['type'] == 'tune_robot' and commands[-1].get('changes') == {'response_ms': 40}, commands[-3:]
            feel.get_by_role('button', name='Reset to startup').click()
            expect(feel.get_by_text('Applied: Fast')).to_be_visible()
            with lock: assert commands[-1].get('startup') is True
            directions = page.get_by_role('region', name='Joint directions')
            directions.get_by_role('switch', name='Wrist roll reversed').click()
            expect(directions.get_by_role('switch', name='Wrist roll reversed')).to_have_attribute('aria-checked', 'true')
            with lock: assert commands[-1]['type'] == 'set_joint_direction' and commands[-1]['joint'] == 'wrist_roll' and commands[-1]['reverse'] is True
            dimensions = page.get_by_role('region', name='Arm dimensions and sensor axes')
            dimensions.get_by_label('Shoulder → elbow (cm)').fill('32')
            dimensions.get_by_role('button', name='Save and recalibrate…').click()
            expect(dimensions.get_by_text('This clears the current calibration', exact=False)).to_be_visible()
            dimensions.get_by_role('button', name='Save and recalibrate', exact=True).click()
            expect(dimensions.get_by_text('Settings saved. Capture pose A to start calibration.')).to_be_visible()
            with lock: assert commands[-1]['type'] == 'configure_arm' and commands[-1]['settings']['upper_cm'] == 32
            coins = page.get_by_role('region', name='Haptic coins')
            coins.get_by_role('button', name='Test 1 s').first.click()
            expect(coins.get_by_text('Running 1.0 s', exact=False)).to_be_visible()
            with lock: assert commands[-1]['type'] == 'test_haptic_motor' and commands[-1]['motor'] == 0 and commands[-1]['action'] == 'test'
            sensors = page.get_by_role('region', name='Sensors')
            expect(sensors.get_by_text('Bicep · S3 / 0x4A')).to_be_visible()
            expect(page.get_by_role('img', name='Your arm as estimated', exact=False)).to_be_visible()
            page.screenshot(path=str(OUTPUT / 'setup-desktop.png'), full_page=True)
            page.set_viewport_size({'width':390,'height':844})
            page.screenshot(path=str(OUTPUT / 'setup-mobile.png'), full_page=True)
            assert page.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'setup mobile overflow'
            page.set_viewport_size({'width':1440,'height':1050})
            page.get_by_role('link', name='Console', exact=True).click()
            expect(panel).to_be_visible()
            tuning.get_by_role('button',name='At 0% endpoint').click()
            expect(tuning.get_by_text('Slider referenced.',exact=True)).to_be_visible()
            tuning.get_by_role('button',name='Enable X control').click()
            expect(tuning.get_by_text('Joystick X controls slider speed; center holds.',exact=True)).to_be_visible()
            tuning.get_by_role('button',name='Release slider').click()
            expect(tuning.get_by_text('Slider released.',exact=True)).to_be_visible()
            replay_button = tuning.get_by_role('button',name='Replay / double-click to record',exact=True)
            expect(replay_button).to_be_enabled()
            replay_button.dblclick(delay=80)
            finish_recording = tuning.get_by_role('button',name='Recording',exact=False)
            expect(finish_recording).to_be_enabled()
            page.wait_for_timeout(450)
            with lock: assert [c['action'] for c in commands if c['type']=='replay_robot']==['record']
            finish_recording.dblclick(delay=80)
            expect(tuning.get_by_text('Recording ready.',exact=True)).to_be_visible()
            page.wait_for_timeout(450)
            with lock: assert [c['action'] for c in commands if c['type']=='replay_robot']==['record','record']
            replay_button.click()
            expect(tuning.get_by_text('Returning to the first pose.',exact=True)).to_be_visible()
            with lock: state['replay'].update(phase='playing',elapsed_s=.5,detail='Replaying motion.')
            expect(tuning.get_by_role('progressbar',name='Replay progress')).to_have_attribute('value','0.5')
            tuning.screenshot(path=str(OUTPUT / 'replay-desktop.png'))
            page.set_viewport_size({'width':390,'height':844})
            tuning.screenshot(path=str(OUTPUT / 'replay-mobile.png'))
            assert page.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'replay mobile overflow'
            page.set_viewport_size({'width':1440,'height':1050})
            tuning.get_by_role('button',name='Stop replay',exact=True).click()
            expect(tuning.get_by_text('Replay stopped.',exact=True)).to_be_visible()
            with lock: options['reject'] = True
            replay_button.click()
            expect(tuning.get_by_text('Replay refused.',exact=True)).to_be_visible()
            with lock:
                options['reject'] = False
                count = len(commands)
            # A single click deferred for double-click detection must be cancelled by disconnect.
            replay_button.click()
            with lock: state['tuning'].update(connected=False,fresh=False)
            expect(replay_button).to_be_disabled()
            page.wait_for_timeout(450)
            with lock:
                assert len(commands)==count
                state['tuning'].update(connected=True,fresh=True)
            expect(replay_button).to_be_enabled()
            change(request=dict(id='another-console', ok=True, detail='Other request.'))
            page.wait_for_timeout(400)
            expect(panel.get_by_role('alert')).to_have_count(0)
            panel.scroll_into_view_if_needed()
            page.screenshot(path=str(OUTPUT / 'desktop.png'), full_page=True)
            recenter.click()
            expect(panel.get_by_text('Get ready · Recenter in pose A · 3s')).to_be_visible()
            panel.get_by_role('button', name='Cancel / hold arm').click()
            expect(panel.get_by_text('Capture cancelled; arm held.', exact=True)).to_be_visible()

            change(can_recenter=False, input_fresh=False, sensors=[True, False, True], detail='Forearm sensor is stale.')
            expect(a).to_be_disabled()
            expect(panel.get_by_text('Forearm · Waiting')).to_be_visible()
            expect(panel.get_by_role('button', name='Stop / hold arm')).to_be_enabled()
            change(input_fresh=True, sensors=[True]*3)
            with lock: options['reject'] = True
            a.click()
            expect(panel.get_by_role('alert')).to_have_text('Controller refused capture.')
            with lock:
                options['reject'] = False
                options['acknowledge'] = False
            a.click()
            expect(panel.get_by_text('Waiting for controller confirmation…')).to_be_visible()
            expect(a).to_be_disabled()
            expect(panel.get_by_role('alert')).to_contain_text('No confirmation', timeout=5000)
            expect(a).to_be_enabled()
            with lock: options['old'] = True
            expect(a).to_be_disabled()
            expect(panel.get_by_text('Unavailable', exact=True)).to_be_visible()
            with lock:
                options['old'] = False
            expect(a).to_be_enabled()
            with lock: options['publish'] = False
            expect(a).to_be_disabled()
            with lock:
                options['publish'] = True
                options['acknowledge'] = True
            change(session='restarted-controller', revision=0, phase='needs_recenter', can_recenter=True, request=None,
                   detail='Saved mounting loaded. Recenter in pose A.',
                   saved_config=dict(path='wearable_test/calibration.local.json',state='loaded',detail='Only recenter in pose A; ranges kept.'))
            expect(panel.get_by_text('Saved configuration loaded',exact=True)).to_be_visible()
            expect(panel.get_by_text('Left saved: 40°')).to_be_visible()
            expect(pan_left).to_be_disabled()
            expect(recenter).to_be_enabled()
            page.set_viewport_size({'width':390, 'height':844})
            tuning.scroll_into_view_if_needed()
            tuning.screenshot(path=str(OUTPUT / 'tuning-mobile.png'))
            panel.scroll_into_view_if_needed()
            page.screenshot(path=str(OUTPUT / 'mobile.png'), full_page=True)
            assert page.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'mobile overflow'
            recenter.focus()
            page.keyboard.press('Enter')
            expect(panel.get_by_text('Get ready · Recenter in pose A · 3s')).to_be_visible()
            page.evaluate('localStorage.clear()')
            page.goto(args.url.rstrip('/') + '/', wait_until='domcontentloaded')
            expect(panel.get_by_text('Calibration uses your three wearable sensors.', exact=False)).to_be_visible()
            expect(panel.get_by_role('button', name='Capture pose A')).to_be_disabled()
            assert not errors, errors
            assert len({c['request_id'] for c in commands}) == len(commands), 'replayed request'
            browser.close()
        server.shutdown()
        thread.join(timeout=2)
    print('PASS: A/B/C/D, learned ranges, progress, recenter, cancel, sensor failure, rejection, timeout, stale timestamps, restart, keyboard, mobile, simulator,'
          ' robot enable/stop/Esc, response profiles, joint directions, arm dimensions, coin tests and the Setup page')


